INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3483174, 486577, 28801, '<td valign="top">Really sweet still-life - definite ribbon candidate!</td>', 'Really sweet still-life - definite ribbon candidate!', '2007-03-23 09:44:32.000000', NULL, 1),
(3483202, 486533, 66353, '<td valign="top">Nice lines and composition</td>', 'Nice lines and composition', '2007-03-23 10:05:05.000000', NULL, 1),
(3483209, 486627, 66353, '<td valign="top">Beautiful... :)</td>', 'Beautiful... :)', '2007-03-23 10:08:08.000000', NULL, 1),
(3483210, 485493, 66353, '<td valign="top">Nice idea...</td>', 'Nice idea...', '2007-03-23 10:08:34.000000', NULL, 1),
(3483212, 486237, 66353, '<td valign="top">excellent red/green composition</td>', 'excellent red/green composition', '2007-03-23 10:09:15.000000', NULL, 1),
(3483277, 486529, 67671, '<td valign="top">As much as I like this shot, I''m not sure it fits the challenge, multiple light sources, it looks to me like a single light source, multiple times, a strobe light, I''m giving it a 5, the frame, timing, rocus, exposure is all really good, good luck.</td>', 'As much as I like this shot, I''m not sure it fits the challenge, multiple light sources, it looks to me like a single light source, multiple times, a strobe light, I''m giving it a 5, the frame, timing, rocus, exposure is all really good, good luck.', '2007-03-23 11:01:24.000000', NULL, 1),
(3483296, 486170, 67671, '<td valign="top">imo, the frame spoils this shot, looking past that, the lighting is wonderfull, and thats what this challenge is about, the white at the bottem of the vase, with the blue at the top, is really good, it''s just that fold in the backdrop, on the left side, that is distracting me, 8</td>', 'imo, the frame spoils this shot, looking past that, the lighting is wonderfull, and thats what this challenge is about, the white at the bottem of the vase, with the blue at the top, is really good, it''s just that fold in the backdrop, on the left side, that is distracting me, 8', '2007-03-23 11:15:54.000000', NULL, 1),
(3483315, 486626, 67671, '<td valign="top">I don''t think that drive is going to work any longer, hope you have a cheap filter on you lens, or it''s a big tellephoto, and you are well back, I like this shot, looks like you are using an angle grinder to through up the sparks, the lighting and color are excelent. good work.</td>', 'I don''t think that drive is going to work any longer, hope you have a cheap filter on you lens, or it''s a big tellephoto, and you are well back, I like this shot, looks like you are using an angle grinder to through up the sparks, the lighting and color are excelent. good work.', '2007-03-23 11:25:05.000000', NULL, 1),
