(3485863, 486529, 65234, '<td valign="top">Impressive image!</td>', 'Impressive image!', '2007-03-24 19:41:40.000000', NULL, 1),
(3485867, 486401, 65234, '<td valign="top">Too cute!!  I like the negative space emphasizing their smallness.</td>', 'Too cute!!  I like the negative space emphasizing their smallness.', '2007-03-24 19:45:03.000000', NULL, 1),
(3485874, 486126, 65234, '<td valign="top">You could change the mood just by changing the color of a light.  Great idea!</td>', 'You could change the mood just by changing the color of a light.  Great idea!', '2007-03-24 19:49:17.000000', NULL, 1),
