(3486064, 486664, 67844, '<td valign="top">Interesting photo. Nice use of light. I would like to see it a bit brighter though and maybe a deeper DOF.</td>', 'Interesting photo. Nice use of light. I would like to see it a bit brighter though and maybe a deeper DOF.', '2007-03-24 21:47:23.000000', NULL, 1),
(3486071, 484368, 67844, '<td valign="top">Interesting take on MLS, using one light source to light another non-working light source to give the allusion the it is working.</td>', 'Interesting take on MLS, using one light source to light another non-working light source to give the allusion the it is working.', '2007-03-24 21:51:48.000000', NULL, 1),
(3486076, 486540, 67844, '<td valign="top">It appears to me that the photo is just slightly off level and I find myself trying to mentally measure each side. I guess what I am trying to say is that it is distracting. Once I get past that, I really like it.</td>', 'It appears to me that the photo is just slightly off level and I find myself trying to mentally measure each side. I guess what I am trying to say is that it is distracting. Once I get past that, I really like it.', '2007-03-24 21:58:06.000000', NULL, 1),
(3486077, 486416, 67844, '<td valign="top">I find this photo too dark and lacking color. It seems a bit bland.</td>', 'I find this photo too dark and lacking color. It seems a bit bland.', '2007-03-24 21:59:55.000000', NULL, 1),
