INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3486532, 485230, 66341, '<td valign="top">Very nice photo with great lighting, but only one light source is obvious to me</td>', 'Very nice photo with great lighting, but only one light source is obvious to me', '2007-03-25 06:28:45.000000', NULL, 1),
(3486543, 486242, 66341, '<td valign="top">I think the photo could be much better if it was rotated so that the horizon is level and the verticals are vertical.</td>', 'I think the photo could be much better if it was rotated so that the horizon is level and the verticals are vertical.', '2007-03-25 06:35:36.000000', NULL, 1),
(3486545, 484977, 66341, '<td valign="top">The picture is very small and I cannot see the detail in it</td>', 'The picture is very small and I cannot see the detail in it', '2007-03-25 06:37:37.000000', NULL, 1),
(3486550, 486596, 66341, '<td valign="top">Nice photo, but only one light source is obvious to me. I think the jewels are too weak in the photo or are lacking contrast. A closer crop or a darker background than the skin may have helped.</td>', 'Nice photo, but only one light source is obvious to me. I think the jewels are too weak in the photo or are lacking contrast. A closer crop or a darker background than the skin may have helped.', '2007-03-25 06:41:00.000000', NULL, 1),
(3486552, 486578, 66341, '<td valign="top">Nice photo, but only one light source is obvious to me</td>', 'Nice photo, but only one light source is obvious to me', '2007-03-25 06:41:47.000000', NULL, 1),
(3486556, 486496, 66341, '<td valign="top">There ARE at least three light sources, but they''re not making the picture. If anything, the one on the right causes distracting shadows.</td>', 'There ARE at least three light sources, but they''re not making the picture. If anything, the one on the right causes distracting shadows.', '2007-03-25 06:43:08.000000', NULL, 1),
(3486557, 485787, 66341, '<td valign="top">Well lit, but little impact. I think if Dolly was looking at the camera and the girl was smiling, the photo would be more appealing</td>', 'Well lit, but little impact. I think if Dolly was looking at the camera and the girl was smiling, the photo would be more appealing', '2007-03-25 06:44:26.000000', NULL, 1),
(3486558, 486464, 66341, '<td valign="top">Nice photo, but only one light source is obvious to me</td>', 'Nice photo, but only one light source is obvious to me', '2007-03-25 06:44:52.000000', NULL, 1),
(3486561, 486613, 66341, '<td valign="top">seems overexposed..</td>', 'seems overexposed..', '2007-03-25 06:46:06.000000', NULL, 1),
(3486563, 485493, 66341, '<td valign="top">Nice idea !  It really really uses multiple light sources to meet the challenge. First 10 out of 120 votes so far</td>', 'Nice idea !  It really really uses multiple light sources to meet the challenge. First 10 out of 120 votes so far', '2007-03-25 06:47:29.000000', NULL, 1),
(3486564, 486228, 66341, '<td valign="top">perfectly exposed.</td>', 'perfectly exposed.', '2007-03-25 06:48:06.000000', NULL, 1),
(3486568, 486182, 66341, '<td valign="top">Not really sure what I''m looking at here</td>', 'Not really sure what I''m looking at here', '2007-03-25 06:49:43.000000', NULL, 1),
(3486571, 485527, 66341, '<td valign="top">It is well exposed, but the shadows below the rafters are distracting (because your flash was higher than your lens, I guess). If you had the camera in the same place but upside down, the flash would light get under the rafters and eliminate those shadows (but you might get some on the pews...)</td>', 'It is well exposed, but the shadows below the rafters are distracting (because your flash was higher than your lens, I guess). If you had the camera in the same place but upside down, the flash would light get under the rafters and eliminate those shadows (but you might get some on the pews...)', '2007-03-25 06:52:21.000000', NULL, 1),
(3486573, 485495, 66341, '<td valign="top">Nice photo, but only one light source is obvious to me</td>', 'Nice photo, but only one light source is obvious to me', '2007-03-25 06:52:45.000000', NULL, 1),
(3486578, 486324, 66341, '<td valign="top">ha ha. nice concept.</td>', 'ha ha. nice concept.', '2007-03-25 06:54:23.000000', NULL, 1),
(3486581, 486472, 66341, '<td valign="top">Nice photo, but only one light source is obvious to me</td>', 'Nice photo, but only one light source is obvious to me', '2007-03-25 06:56:31.000000', NULL, 1),
