(3493598, 486332, 74747, '<td valign="top">Thanks everyone! My highest score yet! I appreciate it!</td>', 'Thanks everyone! My highest score yet! I appreciate it!', '2007-03-28 10:28:39.000000', NULL, 0),
(3493603, 486456, 62989, '<td valign="top">all the light in the original was bright red - it was horrible - there was only 3% red in the channel mix when i destaurated it</td>', 'all the light in the original was bright red - it was horrible - there was only 3% red in the channel mix when i destaurated it', '2007-03-28 10:30:38.000000', NULL, 0),
(3493677, 486529, 63503, '<td valign="top">I don''t mean to be a pest here, I know you''ve already given an explanation about the way you did this, still, it is not clear to me the way the pencils were held with your hands. Were you wearing black gloves? how did you manage to conceal your hand and forearm from the shot? were you all naked and painted pitch black? is that why you chose to place your picture in the nude gallery? :-) . Also, I take it there were 3 bursts of 20 flashes each, I assume you had the shutter open throughout by pressing with your left hand, while you maneuvered the pencils with your other hand, how did you manage to produce the 3 separate bursts? did you have a helper do that? I hope you will take the time to answer. Please know that I am not questioning the legality of your picture, I just want to learn stuff. Thank you.</td>', 'I don''t mean to be a pest here, I know you''ve already given an explanation about the way you did this, still, it is not clear to me the way the pencils were held with your hands. Were you wearing black gloves? how did you manage to conceal your hand and forearm from the shot? were you all naked and painted pitch black? is that why you chose to place your picture in the nude gallery? :-) . Also, I take it there were 3 bursts of 20 flashes each, I assume you had the shutter open throughout by pressing with your left hand, while you maneuvered the pencils with your other hand, how did you manage to produce the 3 separate bursts? did you have a helper do that? I hope you will take the time to answer. Please know that I am not questioning the legality of your picture, I just want to learn stuff. Thank you.', '2007-03-28 10:59:59.000000', NULL, 0),
(3493683, 486529, 24454, '<td valign="top">Woo hooo. . . a first ribbon!  And so deserving!  This is just flat out amazing!  MEGA CONGRATULATIONS!<br/> <br/></td>', 'Woo hooo. . . a first ribbon!  And so deserving!  This is just flat out amazing!  MEGA CONGRATULATIONS! ', '2007-03-28 11:02:48.000000', NULL, 0),
